INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6366781, 942653, 49954, '<td valign="top">Sigh.  Knocking a point for the water drops.  There is not water in a drive and it just seems indulgent.</td>', 'Sigh.  Knocking a point for the water drops.  There is not water in a drive and it just seems indulgent.', '2011-03-30 01:08:46.000000', NULL, 1),
(6366796, 942576, 114285, '<td valign="top">Well composed, one of the better ones.</td>', 'Well composed, one of the better ones.', '2011-03-30 01:10:39.000000', NULL, 1),
(6366806, 942601, 114285, '<td valign="top">Well composed, all the best.</td>', 'Well composed, all the best.', '2011-03-30 01:12:37.000000', NULL, 1),
(6366826, 942508, 47487, '<td valign="top">I have been looking forward to this challenge, and this is the kind of image I was waiting to see. Fascinating. :)</td>', 'I have been looking forward to this challenge, and this is the kind of image I was waiting to see. Fascinating. :)', '2011-03-30 01:18:09.000000', NULL, 1),
(6366832, 943660, 47487, '<td valign="top">Heh! Love the quote! :) Lovely image, too.</td>', 'Heh! Love the quote! :) Lovely image, too.', '2011-03-30 01:18:51.000000', NULL, 1),
(6366838, 943051, 47487, '<td valign="top">Creative, and really visually interesting, too! Nice job!</td>', 'Creative, and really visually interesting, too! Nice job!', '2011-03-30 01:19:45.000000', NULL, 1),
(6366843, 942601, 47487, '<td valign="top">Thanks to the Internet, my kids don''t have to use this method... but I was very familiar with it back in the 80s. :) Great shot! Love the colors and light.</td>', 'Thanks to the Internet, my kids don''t have to use this method... but I was very familiar with it back in the 80s. :) Great shot! Love the colors and light.', '2011-03-30 01:20:48.000000', NULL, 1),
(6366865, 943502, 47487, '<td valign="top">Best so far of the overhead layouts. Very nicely done.</td>', 'Best so far of the overhead layouts. Very nicely done.', '2011-03-30 01:27:59.000000', NULL, 1),
(6366871, 942729, 47487, '<td valign="top">Clever! Nicely done, and well shot, too.</td>', 'Clever! Nicely done, and well shot, too.', '2011-03-30 01:29:06.000000', NULL, 1),
(6366873, 942939, 47487, '<td valign="top">This looks painful. :(</td>', 'This looks painful. :(', '2011-03-30 01:29:33.000000', NULL, 1),
(6366874, 942687, 47487, '<td valign="top">Ouch!</td>', 'Ouch!', '2011-03-30 01:29:49.000000', NULL, 1),
(6366895, 943619, 47487, '<td valign="top">Extra point because I laughed. Nicely done. :)</td>', 'Extra point because I laughed. Nicely done. :)', '2011-03-30 01:33:31.000000', NULL, 1),
(6366899, 943651, 129267, '<td valign="top">Nice clarity and depth of field. Generally when I think of technology, I think of cool colors, and the nice warm yellow glow here strikes me as odd. I wonder if you could have added in the HD cover as the background, or to add one more level of interest.</td>', 'Nice clarity and depth of field. Generally when I think of technology, I think of cool colors, and the nice warm yellow glow here strikes me as odd. I wonder if you could have added in the HD cover as the background, or to add one more level of interest.', '2011-03-30 01:34:25.000000', NULL, 1),
(6366901, 943624, 47487, '<td valign="top">I have a soft spot for clothespins. Nice job. (Reminds me of when I would sit under my mom''s clothesline on spring days and pretend I was a clothespin repairperson. Country children are easily amused.)</td>', 'I have a soft spot for clothespins. Nice job. (Reminds me of when I would sit under my mom''s clothesline on spring days and pretend I was a clothespin repairperson. Country children are easily amused.)', '2011-03-30 01:34:57.000000', NULL, 1),
(6366905, 943409, 47487, '<td valign="top">My favorite of the anatomical ones so far. Like.</td>', 'My favorite of the anatomical ones so far. Like.', '2011-03-30 01:35:53.000000', NULL, 1),
(6366907, 943492, 47487, '<td valign="top">Hee! Love it! Extra point for making me laugh with a nerdjoke.</td>', 'Hee! Love it! Extra point for making me laugh with a nerdjoke.', '2011-03-30 01:36:53.000000', NULL, 1),
(6366909, 943405, 47487, '<td valign="top">Wow, I am not usually a huge fan of the ''make it look grotty on purpose'' shots, but this one packs a punch. Nicely done.</td>', 'Wow, I am not usually a huge fan of the ''make it look grotty on purpose'' shots, but this one packs a punch. Nicely done.', '2011-03-30 01:37:43.000000', NULL, 1),
(6366911, 942655, 129267, '<td valign="top">I like the shadow, but wish you could isolate your light sources better so that there weren''t so many shadows. The shield in the rear is at a weird point between in focus, and OOF. (you also have some sensor dust towards the top of the image)</td>', 'I like the shadow, but wish you could isolate your light sources better so that there weren''t so many shadows. The shield in the rear is at a weird point between in focus, and OOF. (you also have some sensor dust towards the top of the image)', '2011-03-30 01:38:07.000000', NULL, 1),
(6366912, 942840, 47487, '<td valign="top">Cute! As a former cornet player, I can smell the lubricant in my mind right now. :)</td>', 'Cute! As a former cornet player, I can smell the lubricant in my mind right now. :)', '2011-03-30 01:38:15.000000', NULL, 1),
(6366917, 942918, 47487, '<td valign="top">Beautiful. My favorite of the food shots.</td>', 'Beautiful. My favorite of the food shots.', '2011-03-30 01:40:57.000000', NULL, 1),
(6366920, 943077, 129267, '<td valign="top">I''m not sure I get a strong relationship to the topic. I think you''re trying to touch it on a purely conceptual level, so I won''t ding you down too much. As far as the shot goes, the most prominent feature is the date, and not the tip of the feather pen (as I suspect it should be). Some sharper DOF might help. I think if you were to crop this to remove the knife (sword reference), it would still hold the same power, but be more formally beautiful.</td>', 'I''m not sure I get a strong relationship to the topic. I think you''re trying to touch it on a purely conceptual level, so I won''t ding you down too much. As far as the shot goes, the most prominent feature is the date, and not the tip of the feather pen (as I suspect it should be). Some sharper DOF might help. I think if you were to crop this to remove the knife (sword reference), it would still hold the same power, but be more formally beautiful.', '2011-03-30 01:41:39.000000', NULL, 1),
(6366930, 942346, 129267, '<td valign="top">On a formal level, I find this beautiful, and I look forward to reading your info. On a conceptual level, I think the title is the only thing saving this for me. I appreciate the experimental approach, but for this challenge, I really would like to see something in focus/recognizable so that I know what exactly it is that''s being disassembled.</td>', 'On a formal level, I find this beautiful, and I look forward to reading your info. On a conceptual level, I think the title is the only thing saving this for me. I appreciate the experimental approach, but for this challenge, I really would like to see something in focus/recognizable so that I know what exactly it is that''s being disassembled.', '2011-03-30 01:43:48.000000', NULL, 1),
(6366935, 942576, 129267, '<td valign="top">Lovely. I like the border, and it provides great breathing room. My only quirk with this is the competition between the bold red clock arm, and the weird sickly green gear. I think I would have spray painted it white to match the other ones (unless of course there''s a significant reason why it should stand out)</td>', 'Lovely. I like the border, and it provides great breathing room. My only quirk with this is the competition between the bold red clock arm, and the weird sickly green gear. I think I would have spray painted it white to match the other ones (unless of course there''s a significant reason why it should stand out)', '2011-03-30 01:45:39.000000', NULL, 1),
(6366945, 942836, 129267, '<td valign="top">I know it was basic, so you can''t clone the fishing wire out, so I won''t ding too bad for that. In the future you could have shot this on the floor with dowels and putty hidden behind the objects (just have to be careful of shadows). As for this, I find the colors a bit bland, I wonder if this would have been more successful in black and white, or with more contrast?</td>', 'I know it was basic, so you can''t clone the fishing wire out, so I won''t ding too bad for that. In the future you could have shot this on the floor with dowels and putty hidden behind the objects (just have to be careful of shadows). As for this, I find the colors a bit bland, I wonder if this would have been more successful in black and white, or with more contrast?', '2011-03-30 01:48:38.000000', NULL, 1),
(6366952, 942840, 129267, '<td valign="top">Internet memes have got me seeing googly eyes EVERYWHERE. <br/>Formally, this seems a bit bland to me. Everything seems on the same plane, and has equal importance. Maybe some sort of hierarchy, or focus more on some of the beautiful details of the instrument?</td>', 'Internet memes have got me seeing googly eyes EVERYWHERE. Formally, this seems a bit bland to me. Everything seems on the same plane, and has equal importance. Maybe some sort of hierarchy, or focus more on some of the beautiful details of the instrument?', '2011-03-30 01:50:48.000000', NULL, 1),
(6366956, 942729, 129267, '<td valign="top">I like the title. Would building material make a better ''plate''? The eggshell on the sawblade is a nice touch, as is the contrast provided by the brown egg. I''d like to see this cropped a bit more wide, it feels cramped and uncomfortable to me.</td>', 'I like the title. Would building material make a better ''plate''? The eggshell on the sawblade is a nice touch, as is the contrast provided by the brown egg. I''d like to see this cropped a bit more wide, it feels cramped and uncomfortable to me.', '2011-03-30 01:53:53.000000', NULL, 1),
(6366961, 942918, 129267, '<td valign="top">Great background. Feels like it could use a little bit more backlighting.</td>', 'Great background. Feels like it could use a little bit more backlighting.', '2011-03-30 01:54:59.000000', NULL, 1),
(6366966, 943340, 129267, '<td valign="top">I must say, I''m quite curious about how this background was achieved. I see the HD is floating on something. I''d like to say that it''s a LCD screen, but I''m not sure if you''re gelling your light source or not. I expected a lot of HD''s in this challenge. I feel that this could be disassembled further, it feels the same as taking the lid off a piece of tupperware.</td>', 'I must say, I''m quite curious about how this background was achieved. I see the HD is floating on something. I''d like to say that it''s a LCD screen, but I''m not sure if you''re gelling your light source or not. I expected a lot of HD''s in this challenge. I feel that this could be disassembled further, it feels the same as taking the lid off a piece of tupperware.', '2011-03-30 01:58:04.000000', NULL, 1),
(6366969, 943578, 129267, '<td valign="top">I like the grain. I feel this could be cropped further, or zoomed out a bit. It bothers me that there''s only one side of the table shown. I feel conceptually this is a stretch saved by a witty title. (Don''t worry, my entry is the same :D )</td>', 'I like the grain. I feel this could be cropped further, or zoomed out a bit. It bothers me that there''s only one side of the table shown. I feel conceptually this is a stretch saved by a witty title. (Don''t worry, my entry is the same :D )', '2011-03-30 02:00:31.000000', NULL, 1),
(6366998, 943311, 36843, '<td valign="top">good idea , a little harsh on the lighting</td>', 'good idea , a little harsh on the lighting', '2011-03-30 02:12:53.000000', NULL, 1),
(6367002, 942456, 36843, '<td valign="top">tough to light all those black pieces, nice job</td>', 'tough to light all those black pieces, nice job', '2011-03-30 02:14:32.000000', NULL, 1),
(6367005, 943460, 36843, '<td valign="top">I like that you put the battery in to get perspective on the gear sizes</td>', 'I like that you put the battery in to get perspective on the gear sizes', '2011-03-30 02:16:16.000000', NULL, 1),
(6367011, 943502, 36843, '<td valign="top">wow, that''s a lot of work</td>', 'wow, that''s a lot of work', '2011-03-30 02:24:48.000000', NULL, 1),
(6367015, 943630, 36843, '<td valign="top">oh man your in for a rough score with all the gun haters here, lol</td>', 'oh man your in for a rough score with all the gun haters here, lol', '2011-03-30 02:27:36.000000', NULL, 1),
(6367016, 942836, 36843, '<td valign="top">nice job hiding most of the strings</td>', 'nice job hiding most of the strings', '2011-03-30 02:28:55.000000', NULL, 1),
(6367017, 943493, 36843, '<td valign="top">nice job, my mind went somewhere else with that title</td>', 'nice job, my mind went somewhere else with that title', '2011-03-30 02:29:54.000000', NULL, 1),
(6367018, 943492, 36843, '<td valign="top">lol</td>', 'lol', '2011-03-30 02:30:25.000000', NULL, 1),
(6367020, 943051, 36843, '<td valign="top">now this is super cool. It makes me wish I''d thought of it</td>', 'now this is super cool. It makes me wish I''d thought of it', '2011-03-30 02:31:25.000000', NULL, 1),
(6367025, 942653, 36843, '<td valign="top">love the idea</td>', 'love the idea', '2011-03-30 02:32:45.000000', NULL, 1),
(6367031, 943340, 36843, '<td valign="top">just love your backround, what is it?</td>', 'just love your backround, what is it?', '2011-03-30 02:35:45.000000', NULL, 1),
(6367036, 943064, 69487, '<td valign="top">I guess because this was basic you ended up having to still have visible wires.  I also assume they are support the bulb as well.  I will start to make the assumption the screen you edited this on may have looked different.</td>', 'I guess because this was basic you ended up having to still have visible wires.  I also assume they are support the bulb as well.  I will start to make the assumption the screen you edited this on may have looked different.', '2011-03-30 02:37:15.000000', NULL, 1),
(6367042, 942836, 69487, '<td valign="top">I wish i had the time to have done a shot like this, exactly what I think of for this.  Shame about the two lines in the shadows (and the basic) but overall not bad.</td>', 'I wish i had the time to have done a shot like this, exactly what I think of for this.  Shame about the two lines in the shadows (and the basic) but overall not bad.', '2011-03-30 02:38:56.000000', NULL, 1),
(6367046, 943630, 69487, '<td valign="top">One would have to assume you used something to cover the camera to perform the shot.  My question is if it caused the discoloration?  The gun not being there for the last part of the shot (assumption) hurt it a little but made the shot simpler to do.<br/> <br/>If you ever get an off camera flash you can accomplish this again by shooting in total darkness and firing the flash off the ceiling once for the two "exposures".</td>', 'One would have to assume you used something to cover the camera to perform the shot.  My question is if it caused the discoloration?  The gun not being there for the last part of the shot (assumption) hurt it a little but made the shot simpler to do. If you ever get an off camera flash you can accomplish this again by shooting in total darkness and firing the flash off the ceiling once for the two "exposures".', '2011-03-30 02:41:39.000000', NULL, 1),
(6367050, 943071, 107603, '<td valign="top">interesting idea</td>', 'interesting idea', '2011-03-30 02:43:01.000000', NULL, 1),
(6367062, 942939, 105333, '<td valign="top">The negative space on the right works well.</td>', 'The negative space on the right works well.', '2011-03-30 02:55:00.000000', NULL, 1),
(6367065, 943630, 105333, '<td valign="top">The seemingly double exposure isn''t working for me.  I want the pieces to stand out and not be overtaken by the "shadows"</td>', 'The seemingly double exposure isn''t working for me.  I want the pieces to stand out and not be overtaken by the "shadows"', '2011-03-30 02:57:41.000000', NULL, 1),
(6367066, 942346, 105333, '<td valign="top">Interesting patterns.  What is this?</td>', 'Interesting patterns.  What is this?', '2011-03-30 02:58:59.000000', NULL, 1),
(6367069, 942409, 105333, '<td valign="top">Beautiful bokeh.</td>', 'Beautiful bokeh.', '2011-03-30 03:00:38.000000', NULL, 1),
(6367072, 943483, 129267, '<td valign="top">The angle on which the flower is resting feels a bit contrived. I wonder if there''s a way to make this shot without it. I like the border, and the horizontal nature of the shot.</td>', 'The angle on which the flower is resting feels a bit contrived. I wonder if there''s a way to make this shot without it. I like the border, and the horizontal nature of the shot.', '2011-03-30 03:01:58.000000', NULL, 1),
(6367073, 943503, 105333, '<td valign="top">Great symmetry but the light is too harsh.</td>', 'Great symmetry but the light is too harsh.', '2011-03-30 03:03:22.000000', NULL, 1),
(6367076, 942836, 105333, '<td valign="top">The fishline used to hang some of the items detracts from the photo.</td>', 'The fishline used to hang some of the items detracts from the photo.', '2011-03-30 03:04:30.000000', NULL, 1),
(6367078, 943103, 105333, '<td valign="top">Your title made me laugh.  The pattern on the table is too much, a solid background would be better.</td>', 'Your title made me laugh.  The pattern on the table is too much, a solid background would be better.', '2011-03-30 03:07:45.000000', NULL, 1),
(6367079, 943064, 105333, '<td valign="top">The illumination around the lightbulb is fascinating.</td>', 'The illumination around the lightbulb is fascinating.', '2011-03-30 03:09:08.000000', NULL, 1),
(6367080, 942456, 105333, '<td valign="top">That''s a lot of pieces I hope you remember how they all go back together.</td>', 'That''s a lot of pieces I hope you remember how they all go back together.', '2011-03-30 03:09:56.000000', NULL, 1),
(6367081, 942508, 105333, '<td valign="top">The wear and tear on the components gives the feeling that this was a much used fishing reel.</td>', 'The wear and tear on the components gives the feeling that this was a much used fishing reel.', '2011-03-30 03:10:44.000000', NULL, 1),
(6367082, 943493, 129267, '<td valign="top">Nice simple looking photograph. I wonder if there would be a more interesting commentary if you would have arranged the flowers in a more mechanical way. (sorted from largest to smallest perhaps?)</td>', 'Nice simple looking photograph. I wonder if there would be a more interesting commentary if you would have arranged the flowers in a more mechanical way. (sorted from largest to smallest perhaps?)', '2011-03-30 03:11:55.000000', NULL, 1),
(6367084, 943645, 105333, '<td valign="top">I''m torn between liking the fact that not all of the pieces are completely in the frame and being a little annoyed that the 12 is cut off on the face of the clock.</td>', 'I''m torn between liking the fact that not all of the pieces are completely in the frame and being a little annoyed that the 12 is cut off on the face of the clock.', '2011-03-30 03:12:47.000000', NULL, 1),
(6367088, 942986, 105333, '<td valign="top">The orange jumps out with the all black background.  Well done.</td>', 'The orange jumps out with the all black background.  Well done.', '2011-03-30 03:14:31.000000', NULL, 1),
(6367090, 943619, 129267, '<td valign="top">Oh my, clean that gunk out of your printer!  <br/> <br/>do a quick google search for ''lego hello world printer.'' Someone made a printer that uses markers and legos. <br/> <br/>Okay, so on to the photo. The shadows in this are a bit heavy, and the photograph seems almost default (taken from above/front). I wonder what it would have looked like shooting from "over the shoulder" of the legos, or from a more horizontal perspective.</td>', 'Oh my, clean that gunk out of your printer!   do a quick google search for ''lego hello world printer.'' Someone made a printer that uses markers and legos.  Okay, so on to the photo. The shadows in this are a bit heavy, and the photograph seems almost default (taken from above/front). I wonder what it would have looked like shooting from "over the shoulder" of the legos, or from a more horizontal perspective.', '2011-03-30 03:15:19.000000', NULL, 1),
(6367092, 943619, 105333, '<td valign="top">Cute concept but I''m not sure I consider this a disassembled printer.</td>', 'Cute concept but I''m not sure I consider this a disassembled printer.', '2011-03-30 03:15:45.000000', NULL, 1),
(6367094, 943615, 129267, '<td valign="top">I think a title that more heavily referenced the dissection of light would help this out. As far as the photograph goes, it''s a bit busy, I think it would be in your interest to get rid of 2/3''rds of the objects.</td>', 'I think a title that more heavily referenced the dissection of light would help this out. As far as the photograph goes, it''s a bit busy, I think it would be in your interest to get rid of 2/3''rds of the objects.', '2011-03-30 03:17:10.000000', NULL, 1),
(6367096, 943503, 129267, '<td valign="top">Oink. Good concept. I wonder if this could have involved a mirror so you could have gotten rid of that distracting pink logo.</td>', 'Oink. Good concept. I wonder if this could have involved a mirror so you could have gotten rid of that distracting pink logo.', '2011-03-30 03:18:41.000000', NULL, 1),
(6367099, 942719, 129267, '<td valign="top">Hey! I see another screw to be taken apart!<br/> <br/>This meets the challenge, but I would like to see the objects arranged in a more beautiful way.</td>', 'Hey! I see another screw to be taken apart! This meets the challenge, but I would like to see the objects arranged in a more beautiful way.', '2011-03-30 03:21:15.000000', NULL, 1),
(6367102, 943160, 129267, '<td valign="top">Nice texture and lighting.</td>', 'Nice texture and lighting.', '2011-03-30 03:22:55.000000', NULL, 1),
(6367104, 943051, 129267, '<td valign="top">Good form, interesting interpretation. Things are a bit diagonal on the bottom, which seems weird. An inch more on the top would do well I think. 8</td>', 'Good form, interesting interpretation. Things are a bit diagonal on the bottom, which seems weird. An inch more on the top would do well I think. 8', '2011-03-30 03:26:01.000000', NULL, 1),
(6367107, 943500, 129267, '<td valign="top">Good technicals, but it seems a bit default. The warm light strikes me as odd. I think of cool Light when it comes to electronics. Good textures in this for such a smooth surface.</td>', 'Good technicals, but it seems a bit default. The warm light strikes me as odd. I think of cool Light when it comes to electronics. Good textures in this for such a smooth surface.', '2011-03-30 03:27:28.000000', NULL, 1),
(6367112, 942893, 129267, '<td valign="top">The tight crop works well. What if you were to try cropping more out of the frame, and positioning it on a 30-45 degree angle? I dunno. I see this as a fun shot. If we were allowed triptychs, I could see this winning hands down. <br/> <br/>Exposure is great, the bottom right corner bothers me a bit, (hair and seems too light) but the rest is nice.</td>', 'The tight crop works well. What if you were to try cropping more out of the frame, and positioning it on a 30-45 degree angle? I dunno. I see this as a fun shot. If we were allowed triptychs, I could see this winning hands down.  Exposure is great, the bottom right corner bothers me a bit, (hair and seems too light) but the rest is nice.', '2011-03-30 03:33:08.000000', NULL, 1),
(6367118, 943409, 129267, '<td valign="top">Took me a little while to figure out the materials. I love love love the diagonal shadow on the back wall. The highlight on the skull bothers me, but not enough to really sway me. 7</td>', 'Took me a little while to figure out the materials. I love love love the diagonal shadow on the back wall. The highlight on the skull bothers me, but not enough to really sway me. 7', '2011-03-30 03:35:06.000000', NULL, 1),
(6367125, 943654, 129267, '<td valign="top">Good title. Wish the form was a bit more exciting, it seems a bit blobular (that''s totally a word). The focus of this seems to be a bit too far back, I feel like the topmost object (either the gray connection, or the blue transistor) should be more in focus.</td>', 'Good title. Wish the form was a bit more exciting, it seems a bit blobular (that''s totally a word). The focus of this seems to be a bit too far back, I feel like the topmost object (either the gray connection, or the blue transistor) should be more in focus.', '2011-03-30 03:36:54.000000', NULL, 1),
(6367129, 943561, 129267, '<td valign="top">good depth for a top-down image. highlights are a little bright for me. I love the hint of color in the shadows. 6</td>', 'good depth for a top-down image. highlights are a little bright for me. I love the hint of color in the shadows. 6', '2011-03-30 03:37:58.000000', NULL, 1),
(6367130, 943624, 129267, '<td valign="top">seems a bit soft. I think the coolest shadow is the center portion, and I''m sad that I don''t get to see it.</td>', 'seems a bit soft. I think the coolest shadow is the center portion, and I''m sad that I don''t get to see it.', '2011-03-30 03:38:35.000000', NULL, 1),
(6367135, 943630, 129267, '<td valign="top">seems a bit dark. I like the hierarchy of the objects. I''m not sure the reflections are helping in this case, they seem to make almost a double exposure effect on the pistol.</td>', 'seems a bit dark. I like the hierarchy of the objects. I''m not sure the reflections are helping in this case, they seem to make almost a double exposure effect on the pistol.', '2011-03-30 03:40:34.000000', NULL, 1),
(6367138, 943460, 129267, '<td valign="top">On my monitor, it has some of the highlights blown out as well as the shadows. The numbers  are a good leading line, to follow around the image. I wonder if those could have been used to more advantage.</td>', 'On my monitor, it has some of the highlights blown out as well as the shadows. The numbers  are a good leading line, to follow around the image. I wonder if those could have been used to more advantage.', '2011-03-30 03:42:13.000000', NULL, 1),
(6367139, 943343, 129267, '<td valign="top">Love it ... with an exception to that weird sign on the right. I find the isolation of arms to be a good constraint. It needs one more pose, where you actually have your arms recede forward and backwards in space (image yourself standing sideways pointing at the lens) 6</td>', 'Love it ... with an exception to that weird sign on the right. I find the isolation of arms to be a good constraint. It needs one more pose, where you actually have your arms recede forward and backwards in space (image yourself standing sideways pointing at the lens) 6', '2011-03-30 03:45:07.000000', NULL, 1),
(6367140, 942653, 129267, '<td valign="top">It''s a beautiful shot... but I don''t understand at all what water drops have to do with an image being disassembled, so in that sense, it seems kind of gimmicky. If you''re adding this to a portfolio, the bottom left corner shows some excess water drops.</td>', 'It''s a beautiful shot... but I don''t understand at all what water drops have to do with an image being disassembled, so in that sense, it seems kind of gimmicky. If you''re adding this to a portfolio, the bottom left corner shows some excess water drops.', '2011-03-30 03:46:38.000000', NULL, 1),
(6367142, 942516, 129267, '<td valign="top">Summer doesn''t usually make me think of green. Can you warm the color up a bit? <br/> <br/>- Beautiful texture, light, DOF and charisma. Makes me miss my skating days. At this point, it''s my challenge winner. 9</td>', 'Summer doesn''t usually make me think of green. Can you warm the color up a bit?  - Beautiful texture, light, DOF and charisma. Makes me miss my skating days. At this point, it''s my challenge winner. 9', '2011-03-30 03:48:41.000000', NULL, 1),
(6367144, 942456, 129267, '<td valign="top">It''s messy. So many pieces crammed into that little space, huh?<br/> <br/>My biggest gripe here is the bottom horizon being so <strike>unordered</strike> angled/tilted. It''s a tight crop, almost feels accidental. I think cropping more would be the answer. I would try 20px on each side (30 on the top) and see if that helps to make it more dynamic.</td>', 'It''s messy. So many pieces crammed into that little space, huh? My biggest gripe here is the bottom horizon being so unordered angled/tilted. It''s a tight crop, almost feels accidental. I think cropping more would be the answer. I would try 20px on each side (30 on the top) and see if that helps to make it more dynamic.', '2011-03-30 03:51:32.000000', NULL, 1),
