(6367499, 943077, 105333, '<td valign="top">Just having a little tip of the sword on the left isn''t working for me.  I wish that whole space was empty.  Am also struggling to see how this is disassembled.</td>', 'Just having a little tip of the sword on the left isn''t working for me.  I wish that whole space was empty.  Am also struggling to see how this is disassembled.', '2011-03-30 11:42:38.000000', NULL, 1),
(6367502, 943321, 105333, '<td valign="top">Good contrast.</td>', 'Good contrast.', '2011-03-30 11:43:51.000000', NULL, 1),
(6367507, 943343, 105333, '<td valign="top">Cute concept.  Very ghost like.</td>', 'Cute concept.  Very ghost like.', '2011-03-30 11:46:21.000000', NULL, 1),
(6367511, 943340, 105333, '<td valign="top">The colorful background is great but the composition is lacking something.</td>', 'The colorful background is great but the composition is lacking something.', '2011-03-30 11:47:50.000000', NULL, 1),
(6367520, 942462, 105333, '<td valign="top">Ha ha.  Cute composition.  The harsh light and shadow give the impression of a bright sunny day.</td>', 'Ha ha.  Cute composition.  The harsh light and shadow give the impression of a bright sunny day.', '2011-03-30 11:50:43.000000', NULL, 1),
(6367521, 943561, 105333, '<td valign="top">A strong and powerful image.</td>', 'A strong and powerful image.', '2011-03-30 11:51:19.000000', NULL, 1),
(6367524, 943578, 105333, '<td valign="top">Love the grain and textures.</td>', 'Love the grain and textures.', '2011-03-30 11:52:26.000000', NULL, 1),
(6367525, 943502, 38725, '<td valign="top">I really like the order in this shot, although things do seem to be slightly leaning to the right as I look up the center. I also like that you left the strip at the bottom and top.</td>', 'I really like the order in this shot, although things do seem to be slightly leaning to the right as I look up the center. I also like that you left the strip at the bottom and top.', '2011-03-30 11:52:29.000000', NULL, 1),
(6367528, 943321, 38725, '<td valign="top">Nice perspective, I''m not feeling ''disassembled'' though.</td>', 'Nice perspective, I''m not feeling ''disassembled'' though.', '2011-03-30 11:53:35.000000', NULL, 1),
(6367531, 942514, 38725, '<td valign="top">Interesting concept, good DOF.</td>', 'Interesting concept, good DOF.', '2011-03-30 11:53:59.000000', NULL, 1),
(6367533, 942918, 105333, '<td valign="top">A different color background would make the pomegranate stand out.  It is hard to see the seeds as they blend into the background.</td>', 'A different color background would make the pomegranate stand out.  It is hard to see the seeds as they blend into the background.', '2011-03-30 11:54:38.000000', NULL, 1),
(6367535, 942558, 105333, '<td valign="top">I find myself looking more at the reflections in the glass than the rest of the picture.</td>', 'I find myself looking more at the reflections in the glass than the rest of the picture.', '2011-03-30 11:55:40.000000', NULL, 1),
(6367539, 943606, 105333, '<td valign="top">DOF is great.  I see all the components but don''t get a sense that it is disassembled.</td>', 'DOF is great.  I see all the components but don''t get a sense that it is disassembled.', '2011-03-30 11:57:14.000000', NULL, 1),
(6367541, 943311, 105333, '<td valign="top">Beautiful colors.  That must have taken a bit of time to tear apart.</td>', 'Beautiful colors.  That must have taken a bit of time to tear apart.', '2011-03-30 11:58:14.000000', NULL, 1),
(6367542, 943554, 48954, '<td valign="top">Damian!</td>', 'Damian!', '2011-03-30 11:58:25.000000', NULL, 1),
(6367544, 943501, 38725, '<td valign="top">Nice concept, quite dark though.</td>', 'Nice concept, quite dark though.', '2011-03-30 11:58:45.000000', NULL, 1),
(6367546, 943634, 105333, '<td valign="top">I wish the pieces were arranged from tallest to shortest.</td>', 'I wish the pieces were arranged from tallest to shortest.', '2011-03-30 11:59:52.000000', NULL, 1),
(6367548, 942687, 105333, '<td valign="top">A little too dark.</td>', 'A little too dark.', '2011-03-30 12:00:41.000000', NULL, 1),
(6367549, 943051, 105333, '<td valign="top">Great idea and well executed.</td>', 'Great idea and well executed.', '2011-03-30 12:01:36.000000', NULL, 1),
(6367554, 943403, 105333, '<td valign="top">Wonderful sense of action.  Struggling to find how this meets the challenge.</td>', 'Wonderful sense of action.  Struggling to find how this meets the challenge.', '2011-03-30 12:04:35.000000', NULL, 1),
(6367555, 942939, 38725, '<td valign="top">Had to clean my screen before commenting, there seems to be lots of distracting bits over the surface, and an unfortunate strip of light top right. Nice idea though, I hope it went back together OK ;)</td>', 'Had to clean my screen before commenting, there seems to be lots of distracting bits over the surface, and an unfortunate strip of light top right. Nice idea though, I hope it went back together OK ;)', '2011-03-30 12:04:53.000000', NULL, 1),
(6367556, 943651, 38725, '<td valign="top">I like the golden colour cast in this shot.</td>', 'I like the golden colour cast in this shot.', '2011-03-30 12:05:49.000000', NULL, 1),
(6367558, 942653, 105333, '<td valign="top">Not sure the water drops were needed here.  Is a great shot even without them.</td>', 'Not sure the water drops were needed here.  Is a great shot even without them.', '2011-03-30 12:06:22.000000', NULL, 1),
(6367559, 943029, 105333, '<td valign="top">Wonderful composition.</td>', 'Wonderful composition.', '2011-03-30 12:07:33.000000', NULL, 1),
(6367560, 942655, 38725, '<td valign="top">Great idea, ironically it looks slightly over-sharpened.</td>', 'Great idea, ironically it looks slightly over-sharpened.', '2011-03-30 12:07:56.000000', NULL, 1),
(6367565, 943630, 38725, '<td valign="top">I think I must be missing something in this shot.</td>', 'I think I must be missing something in this shot.', '2011-03-30 12:09:49.000000', NULL, 1),
(6367567, 942576, 38725, '<td valign="top">Nice. Clean, stark, simple, interesting, I like it a lot. :)</td>', 'Nice. Clean, stark, simple, interesting, I like it a lot. :)', '2011-03-30 12:10:34.000000', NULL, 1),
(6367570, 943051, 38725, '<td valign="top">Brilliant, one of my favourite shots from this challenge.</td>', 'Brilliant, one of my favourite shots from this challenge.', '2011-03-30 12:12:07.000000', NULL, 1),
(6367571, 943029, 38725, '<td valign="top">Nicely lit and a good idea.</td>', 'Nicely lit and a good idea.', '2011-03-30 12:12:51.000000', NULL, 1),
(6367574, 943460, 38725, '<td valign="top">Nice perspective, a bit dark around the battery and casing though. Difficult to get right with all the white though I''m sure.</td>', 'Nice perspective, a bit dark around the battery and casing though. Difficult to get right with all the white though I''m sure.', '2011-03-30 12:14:37.000000', NULL, 1);
