(6367606, 942585, 38725, '<td valign="top">Those duracells look a little too red, maybe a little too much saturation?</td>', 'Those duracells look a little too red, maybe a little too much saturation?', '2011-03-30 12:29:59.000000', NULL, 1),
(6367607, 942456, 38725, '<td valign="top">Needed to be straighter for me.</td>', 'Needed to be straighter for me.', '2011-03-30 12:31:18.000000', NULL, 1),
(6367609, 943615, 38725, '<td valign="top">Interesting trade you have.. ;)</td>', 'Interesting trade you have.. ;)', '2011-03-30 12:31:59.000000', NULL, 1),
