(6367616, 942918, 38725, '<td valign="top">Lovely colour and light.</td>', 'Lovely colour and light.', '2011-03-30 12:33:36.000000', NULL, 1),
(6367618, 942986, 38725, '<td valign="top">Nicely set up shot but I''m distracted by the marks on the black background (I know, basic editing).</td>', 'Nicely set up shot but I''m distracted by the marks on the black background (I know, basic editing).', '2011-03-30 12:34:53.000000', NULL, 1),
(6367627, 943609, 34059, '<td valign="top">Nice detail, lighting and idea... hope it does well!</td>', 'Nice detail, lighting and idea... hope it does well!', '2011-03-30 12:41:28.000000', NULL, 1),
(6367631, 942329, 34059, '<td valign="top">Welll done, even if I think that many entries have too a shallow dof, here it works well, and together with a good composition it makes a very nice photo. An extra point because it is a Bialetti (kidding!)</td>', 'Welll done, even if I think that many entries have too a shallow dof, here it works well, and together with a good composition it makes a very nice photo. An extra point because it is a Bialetti (kidding!)', '2011-03-30 12:43:26.000000', NULL, 1),
(6367635, 943594, 34059, '<td valign="top">This is the best disassembled hard drive in the challenge, in my opinion. The picture is technically well done and the lifted eyebrow gives a nice humor to it.</td>', 'This is the best disassembled hard drive in the challenge, in my opinion. The picture is technically well done and the lifted eyebrow gives a nice humor to it.', '2011-03-30 12:44:44.000000', NULL, 1),
(6367636, 943143, 105333, '<td valign="top">Ha ha love it.  I have wanted to do that a time or two.  The lighting on the hammer is great.</td>', 'Ha ha love it.  I have wanted to do that a time or two.  The lighting on the hammer is great.', '2011-03-30 12:45:46.000000', NULL, 1),
(6367642, 942601, 34059, '<td valign="top">You know we all have done this when we were kids :)<br/>I like it as it is well executed, and I particularly like that the broken cubes show mainly the colors hidden in the big one. Very very nice!</td>', 'You know we all have done this when we were kids :)I like it as it is well executed, and I particularly like that the broken cubes show mainly the colors hidden in the big one. Very very nice!', '2011-03-30 12:47:07.000000', NULL, 1),
(6367643, 943258, 105333, '<td valign="top">The marker case and paper have a bit of a bluish tint.  Great idea.</td>', 'The marker case and paper have a bit of a bluish tint.  Great idea.', '2011-03-30 12:47:27.000000', NULL, 1),
(6367649, 942836, 34059, '<td valign="top">Too bad that you can see some straws, it takes away from the general impression of "floating in time", which is very nice! Maybe a different lighting would have helped, even if I''m not sure</td>', 'Too bad that you can see some straws, it takes away from the general impression of "floating in time", which is very nice! Maybe a different lighting would have helped, even if I''m not sure', '2011-03-30 12:49:15.000000', NULL, 1),
(6367676, 942601, 119747, '<td valign="top">I was thinking of doing this with a 5x5 i''ve got but really couldn''t be bothered at the thought of putting it back together again haha</td>', 'I was thinking of doing this with a 5x5 i''ve got but really couldn''t be bothered at the thought of putting it back together again haha', '2011-03-30 13:06:05.000000', NULL, 1),
(6367677, 942653, 119747, '<td valign="top">Could do very well, great sharpness</td>', 'Could do very well, great sharpness', '2011-03-30 13:06:18.000000', NULL, 1),
(6367719, 943051, 111541, '<td valign="top">Wonderfully unique idea!</td>', 'Wonderfully unique idea!', '2011-03-30 13:22:29.000000', NULL, 1),
(6367729, 943051, 129091, '<td valign="top">Very nice image...I''m just sitting here wondering why I did not come up with something this good!  10</td>', 'Very nice image...I''m just sitting here wondering why I did not come up with something this good!  10', '2011-03-30 13:24:28.000000', NULL, 1),
(6367730, 943493, 129091, '<td valign="top">Fantastic!  I only wish that I could think more creatively.</td>', 'Fantastic!  I only wish that I could think more creatively.', '2011-03-30 13:24:52.000000', NULL, 1),
(6367733, 942729, 129091, '<td valign="top">Great idea!  Nicely done.</td>', 'Great idea!  Nicely done.', '2011-03-30 13:25:30.000000', NULL, 1),
(6367735, 942576, 129091, '<td valign="top">This is awesome...great idea.</td>', 'This is awesome...great idea.', '2011-03-30 13:25:47.000000', NULL, 1),
(6367736, 943609, 129091, '<td valign="top">Nice!</td>', 'Nice!', '2011-03-30 13:25:59.000000', NULL, 1),
