(6367743, 942462, 129091, '<td valign="top">Great fun image!</td>', 'Great fun image!', '2011-03-30 13:28:10.000000', NULL, 1),
(6367751, 942687, 129091, '<td valign="top">I like your idea...It could be my monitor but the blacks seems to be blending.    Regardless I still gave a good score...I don''t want to rely on my monitor.</td>', 'I like your idea...It could be my monitor but the blacks seems to be blending.    Regardless I still gave a good score...I don''t want to rely on my monitor.', '2011-03-30 13:29:25.000000', NULL, 1),
(6367752, 942601, 129091, '<td valign="top">Great idea!</td>', 'Great idea!', '2011-03-30 13:29:34.000000', NULL, 1),
(6367753, 943343, 38725, '<td valign="top">Great idea, I''m not getting disassembled from it though unfortunately.</td>', 'Great idea, I''m not getting disassembled from it though unfortunately.', '2011-03-30 13:29:53.000000', NULL, 1),
(6367754, 943215, 38725, '<td valign="top">The reflection on the platter draws my eye as it looks like there is a chunk out of it, then the slightly OOF bits next to the platter drag my eye towards them. I''m not decided yet whether that is good or not..</td>', 'The reflection on the platter draws my eye as it looks like there is a chunk out of it, then the slightly OOF bits next to the platter drag my eye towards them. I''m not decided yet whether that is good or not..', '2011-03-30 13:29:58.000000', NULL, 1),
