(6368938, 942601, 44825, '<td valign="top">Like the layout very clean. <br/> <br/>Not a criticism but I might have moved the focus onto the nearest cube and used a shallow DoF to throw the big block out of focus.</td>', 'Like the layout very clean.  Not a criticism but I might have moved the focus onto the nearest cube and used a shallow DoF to throw the big block out of focus.', '2011-03-31 18:13:37.000000', NULL, 1),
(6368940, 942836, 44825, '<td valign="top">Nice concept but IMO the shadowing doesn''t help the overall shot</td>', 'Nice concept but IMO the shadowing doesn''t help the overall shot', '2011-03-31 18:18:46.000000', NULL, 1),
(6368954, 943630, 16106, '<td valign="top">I like the layout of the components, but your editing did not work for me. The purple overlay is confusing and lowers the contrast to the point of muddyness. The crisp machined look that i can sort of make out in your lighting gets lost.</td>', 'I like the layout of the components, but your editing did not work for me. The purple overlay is confusing and lowers the contrast to the point of muddyness. The crisp machined look that i can sort of make out in your lighting gets lost.', '2011-03-31 18:52:51.000000', NULL, 1),
(6368955, 943493, 16106, '<td valign="top">I wish there was a bit more detail in the textures, but the layout and lighting are top notch. Best of the bios.</td>', 'I wish there was a bit more detail in the textures, but the layout and lighting are top notch. Best of the bios.', '2011-03-31 18:54:58.000000', NULL, 1),
(6368956, 942576, 16106, '<td valign="top">Beautifully handled exposure and graphically the best in the challenge. I do wish you had the rest of the clock parts in the image, but the few that you have are put to good use.</td>', 'Beautifully handled exposure and graphically the best in the challenge. I do wish you had the rest of the clock parts in the image, but the few that you have are put to good use.', '2011-03-31 18:55:15.000000', NULL, 1),
(6368957, 942939, 16106, '<td valign="top">Nice colors and tone, but I wish it had a bit more sharpness. I like the eccentric placement, but miss the rest of the F stop ring that exits stage left.</td>', 'Nice colors and tone, but I wish it had a bit more sharpness. I like the eccentric placement, but miss the rest of the F stop ring that exits stage left.', '2011-03-31 18:57:23.000000', NULL, 1),
(6369214, 943409, 54833, '<td valign="top">That''s good! :-) I saw bones, read your title and saw what you shot, well done.</td>', 'That''s good! :-) I saw bones, read your title and saw what you shot, well done.', '2011-03-31 23:11:29.000000', NULL, 1),
