(6375982, 942576, 75713, '<td valign="top">What a great idea .. the hand of the clock looks like it is balancing the inner wheels .. beautifully done. Congratulations</td>', 'What a great idea .. the hand of the clock looks like it is balancing the inner wheels .. beautifully done. Congratulations', '2011-04-06 02:05:18.000000', NULL, 0),
(6375988, 943493, 75713, '<td valign="top">How tedious the task of making sure all the parts were arranged so perfectly .. right down to the small tear on the matching side petals .. delicate, creative and, as usual, photographed perfectly.  Congratulations.</td>', 'How tedious the task of making sure all the parts were arranged so perfectly .. right down to the small tear on the matching side petals .. delicate, creative and, as usual, photographed perfectly.  Congratulations.', '2011-04-06 02:09:39.000000', NULL, 0),
